/**
 * Milestone rows for one project. Names are unique per project by `name_key`
 * (case and surrounding spaces folded). Closed rows stay in the table.
 */
import {
  and,
  asc,
  count,
  eq,
  isNotNull,
  isNull,
  notInArray,
  sql,
} from "drizzle-orm";
import { newId } from "@/lib/id";
import { MilestoneStateError, milestoneNameKey } from "@/lib/milestones";
import { getDb, issues, milestones } from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { CLOSED_ISSUE_STATUSES } from "@/types/issue";
import { livePredicate, orgPredicate } from "./base-repository";
import { compact } from "./_paging";
import { brandId, toMilestone } from "./_mappers";
import type {
  IsoTimestamp,
  IssueId,
  MilestoneId,
  OrgId,
  ProjectId,
} from "@/types/common";
import type { Milestone, MilestoneProgress } from "@/types/milestone";

export async function findMilestoneById(
  orgId: OrgId,
  milestoneId: MilestoneId,
): Promise<Milestone | null> {
  const row = getDb()
    .select()
    .from(milestones)
    .where(
      and(orgPredicate(milestones.orgId, orgId), eq(milestones.id, milestoneId)),
    )
    .get();
  return row ? toMilestone(row) : null;
}

export async function findByNameKey(
  orgId: OrgId,
  projectId: ProjectId,
  nameKey: string,
): Promise<Milestone | null> {
  const row = getDb()
    .select()
    .from(milestones)
    .where(
      and(
        orgPredicate(milestones.orgId, orgId),
        eq(milestones.projectId, projectId),
        eq(milestones.nameKey, nameKey),
      ),
    )
    .get();
  return row ? toMilestone(row) : null;
}

/**
 * Open milestones first, then closed. Within each group, earliest target date
 * first and dateless milestones last; equal dates break by creation, oldest
 * first.
 */
export async function listByProject(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<readonly Milestone[]> {
  const rows = getDb()
    .select()
    .from(milestones)
    .where(
      and(
        orgPredicate(milestones.orgId, orgId),
        eq(milestones.projectId, projectId),
      ),
    )
    .orderBy(
      sql`case when ${milestones.closedAt} is null then 0 else 1 end`,
      sql`case when ${milestones.targetDate} is null then 1 else 0 end`,
      asc(milestones.targetDate),
      asc(milestones.createdAt),
      asc(milestones.id),
    )
    .all();
  return rows.map(toMilestone);
}

export async function countOpen(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<number> {
  const row = getDb()
    .select({ value: count() })
    .from(milestones)
