/**
 * Milestone lifecycle for one project: create, rename, retarget, close, reopen and list.
 *
 * Must call (do not reimplement): assertCan, assertOrgScope, emit, assertNotArchived
 */
import { MAX_OPEN_MILESTONES_PER_PROJECT } from "@/config/constants";
import { isOverdue } from "@/lib/date";
import { emit } from "@/lib/event-bus";
import { MilestoneStateError, milestoneNameKey } from "@/lib/milestones";
import { assertCan } from "@/lib/permissions";
import { assertNotArchived } from "@/lib/soft-delete";
import { assertOrgScope } from "@/lib/tenant";
import * as milestoneRepo from "@/server/repositories/milestone-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import { toIsoTimestamp } from "@/types/common";
import {
  NotFoundError,
  actorEnvelope,
  projectResource,
  requireFound,
} from "./_support";
import type {
  CloseMilestoneInput,
  CreateMilestoneInput,
  UpdateMilestoneInput,
} from "@/schemas/milestone";
import type { MilestoneId, OrgId, ProjectId } from "@/types/common";
import type { IssueId } from "@/types/common";
import type { Actor } from "@/types/member";
import type {
  Milestone,
  MilestoneProgress,
  MilestoneWithProgress,
} from "@/types/milestone";
import type { Project } from "@/types/project";

import "@/server/services/notification-service";

function isUniqueConstraintError(error: unknown): boolean {
  if (typeof error !== "object" || error === null) return false;
  const code = "code" in error ? String((error as { code: unknown }).code) : "";
  if (code === "SQLITE_CONSTRAINT_UNIQUE") return true;
  return error instanceof Error && error.message.includes("UNIQUE constraint failed");
}

function rethrowNameTaken(error: unknown): never {
  if (isUniqueConstraintError(error)) throw new MilestoneStateError("name_taken");
  throw error;
}

async function loadProject(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<Project> {
  return requireFound(
    await projectRepo.findProjectById(orgId, projectId),
    "Project",
    projectId,
  );
}

async function assertNameAvailable(
  orgId: OrgId,
  projectId: ProjectId,
  name: string,
  exceptId?: MilestoneId,
): Promise<void> {
  const taken = await milestoneRepo.findByNameKey(
    orgId,
    projectId,
    milestoneNameKey(name),
  );
  if (taken && taken.id !== exceptId) {
    throw new MilestoneStateError("name_taken");
