/**
 * Puts an issue in an open milestone of its own project, moves it, or clears
 * it. A closed milestone, or one from another project, is refused before any
 * write; an archived issue or project is refused the same way.
 */
export async function setIssueMilestone(
  actor: Actor,
  input: SetIssueMilestoneInput,
): Promise<Issue> {
  assertOrgScope(actor, input.orgId);

  const before = requireFound(
    await issueRepo.findIssueById(input.orgId, input.issueId),
    "Issue",
    input.issueId,
  );
  assertCan(actor, "issue:update", issueResource(before));
  assertNotArchived("Issue", before.id, before);

  const project = requireFound(
    await projectRepo.findProjectById(input.orgId, before.projectId),
    "Project",
    before.projectId,
  );
  assertNotArchived("Project", project.id, project);

  if (input.milestoneId !== null && input.milestoneId !== before.milestoneId) {
    await requireOpenMilestone(input.orgId, before.projectId, input.milestoneId);
  }

  if (before.milestoneId === input.milestoneId) return before;

  return issueRepo.setIssueMilestone(
    input.orgId,
    input.issueId,
    input.milestoneId,
  );
}

async function requireOpenMilestone(
  orgId: OrgId,
  projectId: ProjectId,
  milestoneId: MilestoneId,
): Promise<void> {
  const milestone = requireFound(
    await milestoneRepo.findMilestoneById(orgId, milestoneId),
    "Milestone",
    milestoneId,
  );
  if (milestone.projectId !== projectId) {
    throw new NotFoundError("Milestone", milestoneId);
  }
  if (milestone.closedAt !== null) {
    throw new MilestoneStateError("closed");
  }
}

