import { mkdtempSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { subscribe } from "@/lib/event-bus";
import { MilestoneStateError } from "@/lib/milestones";
import { PermissionDeniedError } from "@/lib/permissions";
import { AlreadyArchivedError } from "@/lib/soft-delete";
import { TenantScopeError } from "@/lib/tenant";
import { runMigrations } from "@/server/db/migrate";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import { registerActivityListeners } from "@/server/services/activity-service";
import * as activityService from "@/server/services/activity-service";
import * as issueService from "@/server/services/issue-service";
import * as milestoneService from "@/server/services/milestone-service";
import * as notificationService from "@/server/services/notification-service";
import { toIsoTimestamp } from "@/types/common";
import type { IsoTimestamp, MilestoneId } from "@/types/common";
import { NotFoundError } from "@/server/services/_support";
import { createTenant, issueInput } from "../private/var/folders/82/dclbn8z5181_3ppfdtp8csd40000gn/T/bench-scratch/7bbc87b5-881c-4aa9-8095-3a163ccf8838/tests/server/_support/fixtures";

const dir = mkdtempSync(join(tmpdir(), "ms-"));
const dbPath = join(dir, "taskflow.db");
process.env.TASKFLOW_DB_PATH = dbPath;

const PAST = "2020-01-01T00:00:00.000Z" as IsoTimestamp;
const SOON = "2026-01-01T00:00:00.000Z" as IsoTimestamp;
const LATER = "2026-06-01T00:00:00.000Z" as IsoTimestamp;
const FUTURE = "2030-01-01T00:00:00.000Z" as IsoTimestamp;

function assert(cond: unknown, message: string): asserts cond {
  if (!cond) throw new Error(message);
}

async function fails<T>(fn: () => Promise<T>): Promise<unknown> {
  try {
    await fn();
  } catch (error) {
    return error;
  }
  throw new Error("expected failure");
}

try {
  await runMigrations(dbPath);
  const detach = registerActivityListeners();
  const tenant = await createTenant("north", "growth");
  const other = await createTenant("other", "growth");
  const actor = tenant.actors.member;
  const orgId = tenant.org.id;
  const projectId = tenant.project.id;

  const denied = await fails(() =>
    milestoneService.createMilestone(tenant.actors.viewer, {
      orgId,
      projectId,
      name: "Nope",
      targetDate: null,
    }),
  );
  assert(denied instanceof PermissionDeniedError, "viewer create");

  const scope = await fails(() =>
    milestoneService.listMilestones(actor, other.org.id, other.project.id),
  );
  assert(scope instanceof TenantScopeError, "cross tenant list");

  const createdEvents: unknown[] = [];
  const offCreated = subscribe("milestone.created", (payload) => {
    createdEvents.push(payload);
  });

  const sooner = await milestoneService.createMilestone(actor, {
    orgId,
    projectId,
    name: "  Sprint  ",
    targetDate: LATER,
  });
  const early = await milestoneService.createMilestone(actor, {
    orgId,
    projectId,
    name: "Early",
    targetDate: SOON,
  });
  const dateless = await milestoneService.createMilestone(actor, {
    orgId,
    projectId,
    name: "Backlog",
    targetDate: null,
  });
  assert(createdEvents.length === 3, "created events");
  assert(sooner.name === "  Sprint  ", "stores given name");

  const taken = await fails(() =>
    milestoneService.createMilestone(actor, {
      orgId,
      projectId,
      name: "sprint",
      targetDate: null,
    }),
  );
  assert(
    taken instanceof MilestoneStateError && taken.reason === "name_taken",
    "name taken",
  );
  assert(createdEvents.length === 3, "no event on refused create");

  const secondProject = await projectRepo.insertProject({
    orgId,
    name: "Other",
    slug: "other",
    key: "OTH",
    description: null,
    visibility: "org",
    leadId: null,
    color: "#6366f1",
    targetDate: null,
  });
  const reused = await milestoneService.createMilestone(actor, {
    orgId,
    projectId: secondProject.id,
    name: "Sprint",
    targetDate: null,
  });
  assert(reused.projectId === secondProject.id, "name reusable elsewhere");

  const openIssue = await issueService.createIssue(
    actor,
    issueInput(orgId, projectId, {
      title: "Open work",
      assigneeId: tenant.userIds.admin,
    }),
  );
  const doneIssue = await issueService.createIssue(actor, {
    ...issueInput(orgId, projectId, {
      title: "Done work",
      assigneeId: tenant.userIds.admin,
    }),
    status: "done",
    milestoneId: sooner.id,
  });
  const archived = await issueService.createIssue(actor, {
    ...issueInput(orgId, projectId, {
      title: "Archived work",
      assigneeId: tenant.userIds.admin,
    }),
    milestoneId: sooner.id,
  });
  await issueService.archiveIssue(actor, orgId, archived.id);
  const unassigned = await issueService.createIssue(actor, {
    ...issueInput(orgId, projectId, { title: "Unassigned" }),
    milestoneId: sooner.id,
  });
  const own = await issueService.createIssue(actor, {
    ...issueInput(orgId, projectId, {
      title: "Mine",
      assigneeId: actor.userId,
    }),
    milestoneId: sooner.id,
  });

  const moved = await issueService.setIssueMilestone(actor, {
    orgId,
    issueId: openIssue.id,
    milestoneId: sooner.id,
  });
  assert(moved.milestoneId === sooner.id, "set milestone");

  const wrongProject = await fails(() =>
    issueService.setIssueMilestone(actor, {
      orgId,
      issueId: openIssue.id,
      milestoneId: reused.id,
    }),
  );
  assert(wrongProject instanceof NotFoundError, "other project milestone");

  const closedTarget = await milestoneService.createMilestone(actor, {
    orgId,
    projectId,
    name: "Old",
    targetDate: PAST,
  });
  await milestoneService.closeMilestone(actor, {
    orgId,
    milestoneId: closedTarget.id,
    moveOpenIssuesTo: null,
  });
  const intoClosed = await fails(() =>
    issueService.createIssue(actor, {
      ...issueInput(orgId, projectId, { title: "Should not exist" }),
      milestoneId: closedTarget.id,
    }),
  );
  assert(
    intoClosed instanceof MilestoneStateError && intoClosed.reason === "closed",
    "create into closed",
  );
  const stillGone = await issueRepo.listIssues({
    orgId,
    projectId,
    limit: 50,
    cursor: null,
    query: "Should not exist",
  });
  assert(stillGone.total === 0, "refused create wrote nothing");

  const progressBefore = await milestoneService.getMilestone(actor, orgId, sooner.id);
  assert(progressBefore.progress.total === 4, `total ${progressBefore.progress.total}`);
  assert(progressBefore.progress.closed === 1, `closed ${progressBefore.progress.closed}`);
  assert(progressBefore.progress.open === 3, `open ${progressBefore.progress.open}`);
  assert(progressBefore.overdue === false, "future target not overdue");

  const overdueMs = await milestoneService.createMilestone(actor, {
    orgId,
    projectId,
    name: "Late",
    targetDate: PAST,
  });
  await issueService.createIssue(actor, {
    ...issueInput(orgId, projectId, { title: "Late issue" }),
    milestoneId: overdueMs.id,
  });
  const overdueView = await milestoneService.getMilestone(actor, orgId, overdueMs.id);
  assert(overdueView.overdue === true, "overdue");

  const futureMs = await milestoneService.createMilestone(actor, {
    orgId,
    projectId,
    name: "Future",
    targetDate: FUTURE,
  });
  await issueService.createIssue(actor, {
    ...issueInput(orgId, projectId, { title: "Future issue" }),
    milestoneId: futureMs.id,
  });
  const futureView = await milestoneService.getMilestone(actor, orgId, futureMs.id);
  assert(futureView.overdue === false, "future not overdue");

  const listed = await milestoneService.listMilestones(actor, orgId, projectId);
  const names = listed.map((row) => row.milestone.name);
  const earlyAt = names.indexOf("Early");
  const sprintAt = names.indexOf("  Sprint  ");
  const backlogAt = names.indexOf("Backlog");
  const oldAt = names.indexOf("Old");
  assert(earlyAt < sprintAt, "earlier date first");
  assert(sprintAt < backlogAt, "dateless last in open");
  assert(backlogAt < oldAt, "closed after open");

  const closedEvents: Array<{ movedIssueIds: readonly string[] }> = [];
  const offClosed = subscribe("milestone.closed", (payload) => {
    closedEvents.push(payload);
  });
  const closeResult = await milestoneService.closeMilestone(actor, {
    orgId,
    milestoneId: sooner.id,
    moveOpenIssuesTo: early.id,
  });
  assert(closedEvents.length === 1, "one close event");
  const movedIds = new Set(closeResult.movedIssueIds);
  assert(movedIds.has(openIssue.id), "open moved");
  assert(movedIds.has(unassigned.id), "unassigned moved");
  assert(movedIds.has(own.id), "actor issue moved");
  assert(!movedIds.has(doneIssue.id), "done stayed");
  assert(!movedIds.has(archived.id), "archived stayed");

  const doneAfter = await issueRepo.findIssueById(orgId, doneIssue.id);
  const archivedAfter = await issueRepo.findIssueById(orgId, archived.id);
  const openAfter = await issueRepo.findIssueById(orgId, openIssue.id);
  assert(doneAfter?.milestoneId === sooner.id, "done remains");
  assert(archivedAfter?.milestoneId === sooner.id, "archived remains");
  assert(openAfter?.milestoneId === early.id, "open went to target");

  const notes = await notificationService.listNotifications(tenant.actors.admin, {
    orgId,
    recipientId: tenant.userIds.admin,
    unreadOnly: false,
    limit: 50,
    cursor: null,
  });
  const milestoneNotes = notes.items.filter(
    (item) => item.kind === "issue_milestone_changed",
  );
  assert(milestoneNotes.length === 1, `admin notes ${milestoneNotes.length}`);
  const ownNotes = await notificationService.listNotifications(actor, {
    orgId,
    recipientId: actor.userId,
    unreadOnly: false,
    limit: 50,
    cursor: null,
  });
  assert(
    ownNotes.items.every((item) => item.kind !== "issue_milestone_changed"),
    "actor not notified",
  );

  const again = await fails(() =>
    milestoneService.closeMilestone(actor, {
      orgId,
      milestoneId: sooner.id,
      moveOpenIssuesTo: null,
    }),
  );
  assert(again instanceof MilestoneStateError && again.reason === "closed", "double close");
  assert(closedEvents.length === 1, "no second close event");

  const selfTarget = await fails(() =>
    milestoneService.closeMilestone(actor, {
      orgId,
      milestoneId: early.id,
      moveOpenIssuesTo: early.id,
    }),
  );
  assert(selfTarget instanceof NotFoundError, "self target");

  const closedDest = await fails(() =>
    milestoneService.closeMilestone(actor, {
      orgId,
      milestoneId: early.id,
      moveOpenIssuesTo: sooner.id,
    }),
  );
  assert(
    closedDest instanceof MilestoneStateError && closedDest.reason === "closed",
    "closed destination",
  );
  const earlyStill = await milestoneService.getMilestone(actor, orgId, early.id);
  assert(earlyStill.milestone.closedAt === null, "refused close unchanged");

  const reopened = await milestoneService.reopenMilestone(actor, orgId, sooner.id);
  assert(reopened.closedAt === null, "reopened");
