  );
  assert(wrongProject instanceof NotFoundError, "other project milestone");

  const closedTarget = await milestoneService.createMilestone(actor, {
    orgId,
    projectId,
    name: "Old",
    targetDate: PAST,
  });
  await milestoneService.closeMilestone(actor, {
    orgId,
    milestoneId: closedTarget.id,
    moveOpenIssuesTo: null,
  });
  const intoClosed = await fails(() =>
    issueService.createIssue(actor, {
      ...issueInput(orgId, projectId, { title: "Should not exist" }),
      milestoneId: closedTarget.id,
    }),
  );
  assert(
    intoClosed instanceof MilestoneStateError && intoClosed.reason === "closed",
    "create into closed",
  );
  const stillGone = await issueRepo.listIssues({
    orgId,
    projectId,
    limit: 50,
    cursor: null,
    query: "Should not exist",
  });
  assert(stillGone.total === 0, "refused create wrote nothing");

  const progressBefore = await milestoneService.getMilestone(actor, orgId, sooner.id);
  assert(progressBefore.progress.total === 4, `total ${progressBefore.progress.total}`);
  assert(progressBefore.progress.closed === 1, `closed ${progressBefore.progress.closed}`);
  assert(progressBefore.progress.open === 3, `open ${progressBefore.progress.open}`);
  assert(progressBefore.overdue === false, "future target not overdue");

  const overdueMs = await milestoneService.createMilestone(actor, {
    orgId,
    projectId,
    name: "Late",
    targetDate: PAST,
  });
  await issueService.createIssue(actor, {
    ...issueInput(orgId, projectId, { title: "Late issue" }),
    milestoneId: overdueMs.id,
  });
  const overdueView = await milestoneService.getMilestone(actor, orgId, overdueMs.id);
  assert(overdueView.overdue === true, "overdue");

  const futureMs = await milestoneService.createMilestone(actor, {
    orgId,
    projectId,
    name: "Future",
    targetDate: FUTURE,
  });
  await issueService.createIssue(actor, {
    ...issueInput(orgId, projectId, { title: "Future issue" }),
    milestoneId: futureMs.id,
  });
  const futureView = await milestoneService.getMilestone(actor, orgId, futureMs.id);
  assert(futureView.overdue === false, "future not overdue");

  const listed = await milestoneService.listMilestones(actor, orgId, projectId);
  const names = listed.map((row) => row.milestone.name);
  const earlyAt = names.indexOf("Early");
  const sprintAt = names.indexOf("  Sprint  ");
  const backlogAt = names.indexOf("Backlog");
  const oldAt = names.indexOf("Old");
  assert(earlyAt < sprintAt, "earlier date first");
  assert(sprintAt < backlogAt, "dateless last in open");
  assert(backlogAt < oldAt, "closed after open");

  const closedEvents: Array<{ movedIssueIds: readonly string[] }> = [];
  const offClosed = subscribe("milestone.closed", (payload) => {
    closedEvents.push(payload);
  });
  const closeResult = await milestoneService.closeMilestone(actor, {
    orgId,
    milestoneId: sooner.id,
    moveOpenIssuesTo: early.id,
  });
  assert(closedEvents.length === 1, "one close event");
  const movedIds = new Set(closeResult.movedIssueIds);
  assert(movedIds.has(openIssue.id), "open moved");
  assert(movedIds.has(unassigned.id), "unassigned moved");
  assert(movedIds.has(own.id), "actor issue moved");
  assert(!movedIds.has(doneIssue.id), "done stayed");
  assert(!movedIds.has(archived.id), "archived stayed");

  const doneAfter = await issueRepo.findIssueById(orgId, doneIssue.id);
  const archivedAfter = await issueRepo.findIssueById(orgId, archived.id);
  const openAfter = await issueRepo.findIssueById(orgId, openIssue.id);
  assert(doneAfter?.milestoneId === sooner.id, "done remains");
  assert(archivedAfter?.milestoneId === sooner.id, "archived remains");
  assert(openAfter?.milestoneId === early.id, "open went to target");

  const notes = await notificationService.listNotifications(tenant.actors.admin, {
    orgId,
    recipientId: tenant.userIds.admin,
    unreadOnly: false,
    limit: 50,
    cursor: null,
  });
  const milestoneNotes = notes.items.filter(
    (item) => item.kind === "issue_milestone_changed",
  );
  assert(milestoneNotes.length === 1, `admin notes ${milestoneNotes.length}`);
  const ownNotes = await notificationService.listNotifications(actor, {
    orgId,
    recipientId: actor.userId,
    unreadOnly: false,
    limit: 50,
    cursor: null,
  });
  assert(
    ownNotes.items.every((item) => item.kind !== "issue_milestone_changed"),
    "actor not notified",
  );

  const again = await fails(() =>
    milestoneService.closeMilestone(actor, {
      orgId,
      milestoneId: sooner.id,
      moveOpenIssuesTo: null,
    }),
  );
  assert(again instanceof MilestoneStateError && again.reason === "closed", "double close");
  assert(closedEvents.length === 1, "no second close event");

  const selfTarget = await fails(() =>
    milestoneService.closeMilestone(actor, {
      orgId,
      milestoneId: early.id,
      moveOpenIssuesTo: early.id,
    }),
  );
  assert(selfTarget instanceof NotFoundError, "self target");

  const closedDest = await fails(() =>
    milestoneService.closeMilestone(actor, {
      orgId,
      milestoneId: early.id,
      moveOpenIssuesTo: sooner.id,
    }),
  );
  assert(
    closedDest instanceof MilestoneStateError && closedDest.reason === "closed",
    "closed destination",
  );
  const earlyStill = await milestoneService.getMilestone(actor, orgId, early.id);
  assert(earlyStill.milestone.closedAt === null, "refused close unchanged");

  const reopened = await milestoneService.reopenMilestone(actor, orgId, sooner.id);
  assert(reopened.closedAt === null, "reopened");
  const reopenOpen = await fails(() =>
    milestoneService.reopenMilestone(actor, orgId, sooner.id),
  );
  assert(
    reopenOpen instanceof MilestoneStateError && reopenOpen.reason === "already_open",
    "reopen open",
  );

  const renamed = await milestoneService.updateMilestone(actor, {
    orgId,
    milestoneId: sooner.id,
    name: "Sprint Two",
    targetDate: PAST,
  });
  assert(renamed.name === "Sprint Two", "renamed");
  assert(renamed.targetDate === PAST, "retargeted");

  const openNow = (await milestoneService.listMilestones(actor, orgId, projectId)).filter(
    (row) => row.milestone.closedAt === null,
  ).length;
  for (let i = openNow; i < 10; i += 1) {
    await milestoneService.createMilestone(actor, {
      orgId,
      projectId,
      name: `Cap ${i}`,
      targetDate: null,
    });
  }
  const capped = await fails(() =>
    milestoneService.createMilestone(actor, {
      orgId,
      projectId,
      name: "One more",
      targetDate: null,
    }),
  );
  assert(
    capped instanceof MilestoneStateError && capped.reason === "too_many_open",
    "cap",
  );
  await milestoneService.closeMilestone(actor, {
    orgId,
    milestoneId: dateless.id,
    moveOpenIssuesTo: null,
  });
  const afterRoom = await milestoneService.createMilestone(actor, {
    orgId,
    projectId,
    name: "After room",
    targetDate: null,
  });
  const reopenCap = await fails(() =>
    milestoneService.reopenMilestone(actor, orgId, dateless.id),
  );
  assert(
    reopenCap instanceof MilestoneStateError && reopenCap.reason === "too_many_open",
    "reopen cap",
  );
  void afterRoom;

  await projectRepo.archiveProject(orgId, secondProject.id);
  const archivedWrite = await fails(() =>
    milestoneService.createMilestone(actor, {
      orgId,
      projectId: secondProject.id,
      name: "Archived project",
      targetDate: null,
    }),
  );
  assert(archivedWrite instanceof AlreadyArchivedError, "archived project write");
  const stillListed = await milestoneService.listMilestones(
    actor,
    orgId,
    secondProject.id,
  );
  assert(stillListed.length === 1, "list archived project");

  const activity = await activityService.listActivity(actor, {
    orgId,
    limit: 100,
    cursor: null,
    projectId,
  });
  const actions = activity.items.map((item) => item.action);
  assert(actions.includes("milestone.created"), "audit created");
  assert(actions.includes("milestone.closed"), "audit closed");
  assert(actions.includes("milestone.reopened"), "audit reopened");

  offCreated();
  offClosed();
  detach();
  console.log("milestone checks passed");
} finally {
  rmSync(dir, { recursive: true, force: true });
}
